import {Helmet} from "react-helmet-async";
import image from "../images/photos/teapony.png";

const aboutme = {
	"name": "Bonnie",
	"nickname": "Starcatcher",
	"site_name": "Starcatcher Website",
	"color": "#c6a0f6",
	"pronounce": "she/they/it",
	"intrests": "Stars, Ponies, Drawing, Programing, Music, Technology and probably so much more",
	"aboutme": "Hi I'm ${name} ${pronounce} and this is my website where i share my work. I make many types of art like pixel art, 3d models, minecraft mods, music and more. I hope you enjoy spending time on this site.",
	"short": "Hi I'm ${name} ${pronounce} and I make stuff come here to watch what I make.",
	"image": image
}

export function GetAboutMe() {
	aboutme.aboutme = aboutme.aboutme.replace("${name}", aboutme.name).replace("${pronounce}", aboutme.pronounce);
	aboutme.short = aboutme.short.replace("${name}", aboutme.name).replace("${pronounce}", aboutme.pronounce);
	return aboutme;
}

export default function Main() {
	return (
		<>
			<Helmet>
				<title>Pony Website</title>
				<meta property="og:type" content="website"/>
				<meta name="theme-color" content={GetAboutMe().color}/>
				<meta property="og:url" content="https://starcatcher21.github.io/"/>
				<meta property="og:title" content="Website about diffrent form of art"/>
				<meta property="og:description" content={GetAboutMe().aboutme}/>
				<meta property="og:image" content={GetAboutMe().image}/>
				<meta property="og:image:width" content="1200"/>
				<meta property="og:image:height" content="1200"/>
				<meta property="og:site_name" content="Starcatcher Website"/>

				<meta property="twitter:card" content="summary_small_image"/>
				<meta property="twitter:url" content="https://starcatcher21.github.io/"/>
				<meta property="twitter:title" content="Website about diffrent form of art"/>
				<meta property="twitter:image" content={GetAboutMe().image}/>
			</Helmet>

			<a href="https://starcatcher21.github.io/playlist.html">website work in progress enjoy playlist</a>
		</>
	)
}
